use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn main () -> Result < () > { println ! ("🔍 COMPLEXITY ANALYZER - Finding Most Complex Objects") ; println ! ("====================================================") ; let search_paths = vec ! ["submodules/rust/compiler" , "submodules/rust/library" , "src" ,] ; let mut all_reports = Vec :: new () ; for search_path in search_paths { let path = Path :: new (search_path) ; if path . exists () { println ! ("\n📂 Analyzing: {}" , search_path) ; let rust_files = find_rust_files (path) ; println ! ("   Found {} Rust files" , rust_files . len ()) ; for file_path in rust_files . iter () . take (100) { if let Ok (reports) = analyze_rust_file (file_path) { all_reports . extend (reports) ; } } } } all_reports . sort_by (| a , b | b . complexity . cmp (& a . complexity)) ; println ! ("\n🎯 TOP 20 MOST COMPLEX OBJECTS:") ; println ! ("================================") ; for (i , report) in all_reports . iter () . take (20) . enumerate () { println ! ("{}. {} (Complexity: {})" , i + 1 , report . name , report . complexity) ; println ! ("   Fields: {}, Variants: {}, Depth: {}" , report . field_count , report . variant_count , report . nested_depth) ; println ! ("   File: {}" , report . file_path) ; println ! () ; } let complex_objects : Vec < _ > = all_reports . iter () . filter (| r | r . complexity >= 7) . collect () ; println ! ("🔥 COMPLEXITY LEVEL 7+ OBJECTS:") ; println ! ("===============================") ; for report in & complex_objects { println ! ("• {} (Level {})" , report . name , report . complexity) ; println ! ("  {} fields, {} variants, depth {}" , report . field_count , report . variant_count , report . nested_depth) ; } println ! ("\n📊 SUMMARY:") ; println ! ("Total objects analyzed: {}" , all_reports . len ()) ; println ! ("Complexity 7+ objects: {}" , complex_objects . len ()) ; Ok (()) }